"use client";

import { useCallback, useMemo } from "react";
import useSWRInfinite from "swr/infinite";
import type { MessageSingleton } from "@/types/chat"; // your existing type

// ── What your API route returns ──────────────────────────────
type MessagesPageResponse = {
  messages: MessageSingleton<true>[];
  nextCursor: string | null;
  totalCount?: number;
};

// ── What the hook returns ────────────────────────────────────
export type UseMessagesReturn = {
  messages: MessageSingleton<true>[];
  totalCount: number | undefined;
  hasMore: boolean;
  isLoadingInitial: boolean;
  isLoadingMore: boolean;
  error: Error | undefined;
  mutate: ReturnType<typeof useSWRInfinite<MessagesPageResponse, Error>>["mutate"];
  loadMore: () => void;
};

// ── Fetcher ──────────────────────────────────────────────────
const messagesFetcher = async (url: string): Promise<MessagesPageResponse> => {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status}: ${res.statusText}`);
  return res.json<MessagesPageResponse>();
};

const PAGE_SIZE = 25 as const;

// ── Hook ─────────────────────────────────────────────────────
export function useMessages(
  userId: string | undefined,
  conversationId: string | undefined,
  initialPage?: MessagesPageResponse
): UseMessagesReturn {

  // ── Key function (the only real difference from useConversations) ──
  const getKey = useCallback(
    (pageIndex: number, previousPageData: MessagesPageResponse | null) => {
      // No user/convo = don't fetch (same pattern as your useConversations)
      if (!userId || !conversationId) return null;

      // Previous page said "no more" = stop
      if (previousPageData && previousPageData.nextCursor === null) return null;

      const base = `/api/users/${userId}/chat/${conversationId}/messages?limit=${PAGE_SIZE}`;

      // Page 0: most recent, include count
      if (pageIndex === 0) return `${base}&count=1`;

      // Page N: older messages, cursor from previous page
      const cursor = previousPageData?.nextCursor;
      return cursor ? `${base}&before=${cursor}` : null;
    },
    [userId, conversationId]
  );

  // ── SWR Infinite (same config philosophy as your useConversations) ──
  const { data, error, size, setSize, mutate, isValidating, isLoading } =
    useSWRInfinite<MessagesPageResponse, Error>(getKey, messagesFetcher, {
      revalidateFirstPage: false,   // ← don't refetch page 1 on every loadMore
      revalidateOnFocus: false,     // same as your useConversations
      revalidateOnReconnect: false, // same
      revalidateIfStale: false,     // same
      revalidateAll: false,         // don't refetch ALL pages on any mutation
      persistSize: true,            // keep loaded page count across revalidations
      dedupingInterval: 60000,      // same as your useConversations
      errorRetryCount: 2,           // same
      fallbackData: initialPage ? [initialPage] : undefined
    });

  // ── Flatten pages → single chronological array ─────────────
  // SWR gives us [newestPage, olderPage, oldestPage]
  // Each page internally is ASC (oldest→newest within that page)
  // We reverse the page array so oldest page comes first, then concat
  const messages = useMemo(() => {
    if (!data) return [] satisfies MessageSingleton<true>[];
    const seen = new Set<string>();
    const out: MessageSingleton<true>[] = [];

    for (let i = data.length - 1; i >= 0; i--) {
      const page = data[i];
      if (!page) continue;
      for (const msg of page.messages) {
        if (seen.has(msg.id)) continue;
        seen.add(msg.id);
        out.push(msg);
      }
    }
    return out;
  }, [data]);

  // ── Derived state ──────────────────────────────────────────
  const hasMore = data
    ? (data[data.length - 1]?.nextCursor ?? null) !== null
    : true;
  const totalCount = data?.[0]?.totalCount;
  const isLoadingMore = isValidating && size > 1;

  const loadMore = useCallback(() => {
    if (hasMore && !isLoadingMore) setSize(s => s + 1);
  }, [hasMore, isLoadingMore, setSize]);

  // ── Return (same "hook returns everything" shape as useConversations) ──
  return {
    messages,
    totalCount,
    hasMore,
    isLoadingInitial: isLoading,
    isLoadingMore,
    error,
    mutate,
    loadMore
  };
}
